                            result.baseAddress.unsafelyUnwrapped,
                            &a,
                            where: &mask
                        )
                        return unsafe result.baseAddress.unsafelyUnwrapped.move()
                    }
                }(),
                { () -> SIMD<UInt32> in
                    var a = a
                    var mask = mask
                    return withUnsafeTemporaryAllocation(of: SIMD<UInt32>.self, capacity: 1) {
                        result in
                        unsafe highwayLeadingZeroBitCountWhereU32InVectorCode(
                            result.baseAddress.unsafelyUnwrapped,
                            &a,
                            where: &mask
                        )
                        return unsafe result.baseAddress.unsafelyUnwrapped.move()
                    }
                }(),
                "mask: \(describe(mask)), a: \(describe(a))"
            )
        }
        mismatches.record()
    }

